'use strict';
(()=>{
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s)),missions=window.MISSIONS;
let filter='all',returnFocus=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
window.explorerMotion={paused:reduced.matches};
function motion(paused){window.explorerMotion.paused=paused;document.documentElement.classList.toggle('is-paused',paused);$('.motion-control').setAttribute('aria-pressed',String(paused));$('.motion-control').setAttribute('aria-label',paused?'Play animation':'Pause animation');$('.motion-control span').textContent=paused?'\u25b6':'\u2161';window.dispatchEvent(new Event('motionchange'))}
$('.motion-control').addEventListener('click',()=>motion(!window.explorerMotion.paused));reduced.addEventListener('change',e=>motion(e.matches));motion(reduced.matches);
function render(){const q=$('#search').value.trim().toLowerCase(),found=missions.filter(m=>(filter==='all'||m.world===filter)&&`${m.name} ${m.kind} ${m.world} ${m.place} ${m.years}`.toLowerCase().includes(q));$('#archive-list').innerHTML=found.map(m=>`<a class="archive-row" href="#story-${m.id}"><span class="number">${m.number}</span><span class="archive-thumb"><img src="assets/${m.image}" alt="" loading="lazy"></span><span class="archive-name"><h3>${m.name}</h3><span>${m.kind}</span></span><span class="archive-destination">${m.world.toUpperCase()}</span><span class="archive-date">${m.years}</span><span class="archive-arrow" aria-hidden="true">&#8599;</span></a>`).join('');$('#empty-state').hidden=!!found.length;$('#result-count').textContent=`${found.length} explorers found`;window.dispatchEvent(new Event('archiveupdate'))}
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on)});render()}));$('#search').addEventListener('input',render);$('#clear-search').addEventListener('click',()=>{$('#search').value='';$('[data-filter="all"]').click();$('#search').focus()});render();
function menu(open){$('#menu').hidden=!open;$('.menu-control').setAttribute('aria-expanded',open);document.body.classList.toggle('menu-open',open);document.body.classList.toggle('locked',open);if(open)$('#menu a').focus();else $('.menu-control').focus({preventScroll:true})}
$('.menu-control').addEventListener('click',()=>menu($('#menu').hidden));$$('#menu a').forEach(a=>a.addEventListener('click',()=>menu(false)));
document.addEventListener('keydown',e=>{if($('#menu').hidden)return;if(e.key==='Escape')menu(false);if(e.key==='Tab'){const links=[$('.menu-control'),...$$('#menu a')],i=links.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();links.at(-1).focus()}else if(!e.shiftKey&&i===links.length-1){e.preventDefault();links[0].focus()}}});
$('#source-list').innerHTML=missions.map(m=>`<a href="${m.source}" target="_blank" rel="noopener noreferrer">${m.sourceLabel}<span>&#8599;</span></a>`).join('');$('#sources-button').addEventListener('click',()=>{returnFocus=document.activeElement;$('#sources-dialog').showModal();document.body.classList.add('locked')});$$('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('close',()=>{document.body.classList.remove('locked');returnFocus?.focus({preventScroll:true})});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
// Keep attribution with the locally bundled adaptations of the planetary maps.
const credits=document.createElement('p');credits.innerHTML='Planetary maps: <a href="https://www.solarsystemscope.com/textures/" target="_blank" rel="noopener noreferrer">Solar System Scope / INOVE</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Adapted into lit sphere renders with cloud compositing and atmospheric shading.';document.querySelector('.sources-content').append(credits);
// The complete content is visible even before JavaScript or without animation.
$$('.reveal').forEach(e=>e.classList.add('visible'));
})();
